import{_ as r,a0 as t,w as l,s as d,I as n,x as a,a1 as i,A as p,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 mergefs 增加虚拟存储 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mergefs 增加虚拟存储 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mergefs 增加虚拟存储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mergefs 增加虚拟存储 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200501 Using mergerfs to increase your virtual storage","title":"使用 mergefs 增加虚拟存储","tag":"202005","desc":""},"relativePath":"202005/20200501 Using mergerfs to increase your virtual storage.md","filePath":"[post].md"}'),g={name:"202005/20200501 Using mergerfs to increase your virtual storage.md"};function u(c,s,m,f,k,h){const e=t("Link");return l(),d("div",null,[s[22]||(s[22]=n("h1",{id:"使用-mergefs-增加虚拟存储",tabindex:"-1"},[a("使用 mergefs 增加虚拟存储 "),n("a",{class:"header-anchor",href:"#使用-mergefs-增加虚拟存储","aria-label":"Permalink to “使用 mergefs 增加虚拟存储”"},"​")],-1)),s[23]||(s[23]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/04/mergerfs-816x346.png",alt:""})],-1)),s[24]||(s[24]=n("p",null,"如果你想在一个媒体项目中用到了多个磁盘或分区，不想丢失任何现有数据，但又想将所有文件都存放在一个驱动器下，该怎么办？这时，mergefs 就能派上用场！",-1)),n("p",null,[i(e,{href:"https://github.com/trapexit/mergerfs"},{default:p(()=>[...s[0]||(s[0]=[a("mergerfs",-1)])]),_:1}),s[1]||(s[1]=a(" 是一个联合文件系统，旨在简化存储和管理众多商业存储设备上的文件。",-1))]),n("p",null,[s[4]||(s[4]=a("你需要从他们的 ",-1)),i(e,{href:"https://github.com/trapexit/mergerfs/releases"},{default:p(()=>[...s[2]||(s[2]=[a("GitHub",-1)])]),_:1}),s[5]||(s[5]=a(" 页面获取最新的 RPM。Fedora 的版本名称中带有 “fc” 和版本号。例如，这是 Fedora 31 的版本： ",-1)),i(e,{href:"https://github.com/trapexit/mergerfs/releases/download/2.29.0/mergerfs-2.29.0-1.fc31.x86_64.rpm"},{default:p(()=>[...s[3]||(s[3]=[a("mergerfs-2.29.0-1.fc31.x86_64.rpm",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[25]||(s[25]=o(`<h3 id="安装和配置-mergefs" tabindex="-1">安装和配置 mergefs <a class="header-anchor" href="#安装和配置-mergefs" aria-label="Permalink to “安装和配置 mergefs”">​</a></h3><p>使用 <code>sudo</code> 安装已下载的 mergefs 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mergerfs-2.29.0-1.fc31.x86_64.rpm</span></span></code></pre></div><p>现在，你可以将多个磁盘挂载为一个驱动器。如果你有一台媒体服务器，并且希望所有媒体文件都显示在一个地方，这将很方便。如果将新文件上传到系统，那么可以将它们复制到 mergefs 目录，mergefs 会自动将它们复制具有足够可用空间的磁盘上。</p><p>这是使你更容易理解的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1      ext4      23M  386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1      ext4      44M  1.1M 40M 3% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk1/Videos/</span></span>
<span class="line"><span>total 1</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk2/Videos/</span></span>
<span class="line"><span>total 2</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span></code></pre></div><p>在此例中挂载了两块磁盘，分别为 <code>disk1</code> 和 <code>disk2</code>。两个驱动器都有一个包含文件的 <code>Videos</code> 目录。</p><p>现在，我们将使用 mergefs 挂载这些驱动器，使它们看起来像一个更大的驱动器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mergerfs -o defaults,allow_other,use_ino,category.create=mfs,moveonenospc=true,minfreespace=1M /disk1:/disk2 /media</span></span></code></pre></div><p>mergefs 手册页非常庞杂，因此我们将说明上面提到的选项。</p><ul><li><code>defaults</code>：除非指定，否则将使用默认设置。</li><li><code>allow_other</code>：允许 <code>sudo</code> 或 <code>root</code> 以外的用户查看文件系统。</li><li><code>use_ino</code>：让 mergefs 提供文件/目录 inode 而不是 libfuse。虽然不是默认值，但建议你启用它，以便链接的文件共享相同的 inode 值。</li><li><code>category.create=mfs</code>：根据可用空间在驱动器间传播文件。</li><li><code>moveonenospc=true</code>：如果启用，那么如果写入失败，将进行扫描以查找具有最大可用空间的驱动器。</li><li><code>minfreespace=1M</code>：最小使用空间值。</li><li><code>disk1</code>：第一块硬盘。</li><li><code>disk2</code>：第二块硬盘。</li><li><code>/media</code>：挂载驱动器的目录。</li></ul><p>看起来是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1  ext4           23M      386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1  ext4           44M      1.1M 40M 3% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ df -hT | grep media</span></span>
<span class="line"><span>1:2        fuse.mergerfs  66M      1.4M 60M 3% /media</span></span></code></pre></div><p>你可以看到现在 mergefs 挂载显示的总容量为 66M，这是两块硬盘的总容量。</p><p>继续示例：</p><p>有一个叫 <code>Baby&#39;s second Xmas.mkv</code> 的 30M 视频。让我们将其复制到用 mergerfs 挂载的 <code>/media</code> 文件夹中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh &quot;Baby&#39;s second Xmas.mkv&quot;</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30M Apr 20 08:45 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>$ cp &quot;Baby&#39;s second Xmas.mkv&quot; /media/Videos/</span></span></code></pre></div><p>这是最终结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1  ext4          23M 386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1  ext4          44M 31M 9.8M 76% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ df -hT | grep media</span></span>
<span class="line"><span>1:2        fuse.mergerfs 66M 31M 30M 51% /media</span></span></code></pre></div><p>从磁盘空间利用率中可以看到，因为 <code>disk1</code> 没有足够的可用空间，所以 mergefs 自动将文件复制到 <code>disk2</code>。</p><p>这是所有文件详情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /disk1/Videos/</span></span>
<span class="line"><span>total 1</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk2/Videos/</span></span>
<span class="line"><span>total 30003</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30720000 Apr 20 08:47 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /media/Videos/</span></span>
<span class="line"><span>total 30004</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30720000 Apr 20 08:47 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span></code></pre></div><p>当你将文件复制到 mergefs 挂载点时，它将始终将文件复制到有足够可用空间的硬盘上。如果池中的所有驱动器都没有足够的可用空间，那么你将无法复制它们。</p><hr>`,24)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/using-mergerfs-to-increase-your-virtual-storage/"},{default:p(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/using-mergerfs-to-increase-your-virtual-storage/",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/rcurtiswarfield/"},{default:p(()=>[...s[9]||(s[9]=[a("Curt Warfield",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const M=r(g,[["render",u]]);export{y as __pageData,M as default};
